PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(tg_id INTEGER PRIMARY KEY,username TEXT,first_name TEXT,last_name TEXT,created_at DATETIME NOT NULL DEFAULT(datetime('now')),last_seen_at DATETIME,is_banned INTEGER NOT NULL DEFAULT 0,role TEXT NOT NULL DEFAULT 'user',language TEXT NOT NULL DEFAULT 'en',timezone TEXT NOT NULL DEFAULT 'UTC',storage_used INTEGER NOT NULL DEFAULT 0,storage_limit INTEGER NOT NULL DEFAULT 104857600,alias_limit INTEGER NOT NULL DEFAULT 5,totp_secret TEXT,totp_enabled INTEGER NOT NULL DEFAULT 0,totp_recovery_codes TEXT,settings_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS aliases(address TEXT PRIMARY KEY,tg_id INTEGER NOT NULL,domain TEXT NOT NULL,alias_type TEXT NOT NULL DEFAULT 'throwaway',label TEXT,forward_to TEXT,forward_verified INTEGER NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT(datetime('now')),expires_at DATETIME,active INTEGER NOT NULL DEFAULT 1,auto_reply_enabled INTEGER NOT NULL DEFAULT 0,auto_reply_subject TEXT,auto_reply_body TEXT,auto_reply_cooldown_hours INTEGER NOT NULL DEFAULT 24,burner INTEGER NOT NULL DEFAULT 0,burner_expires_at DATETIME,pgp_public_key TEXT,tag_ids TEXT NOT NULL DEFAULT '[]',notes TEXT,FOREIGN KEY(tg_id)REFERENCES users(tg_id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS emails(id INTEGER PRIMARY KEY AUTOINCREMENT,alias_address TEXT NOT NULL,message_id TEXT,thread_id TEXT,sender TEXT NOT NULL,sender_name TEXT,recipient TEXT,reply_to TEXT,subject TEXT,text_body TEXT,html_body TEXT,clean_html TEXT,has_attachments INTEGER NOT NULL DEFAULT 0,is_read INTEGER NOT NULL DEFAULT 0,is_starred INTEGER NOT NULL DEFAULT 0,is_deleted INTEGER NOT NULL DEFAULT 0,spam_score REAL NOT NULL DEFAULT 0,spam_classification TEXT NOT NULL DEFAULT 'ham',spf_result TEXT,dkim_result TEXT,dmarc_result TEXT,origin_ip TEXT,origin_hostname TEXT,origin_country TEXT,origin_asn TEXT,raw_eml_path TEXT,size_bytes INTEGER NOT NULL DEFAULT 0,received_at DATETIME NOT NULL DEFAULT(datetime('now')),expires_at DATETIME,FOREIGN KEY(alias_address)REFERENCES aliases(address)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attachments(id INTEGER PRIMARY KEY AUTOINCREMENT,email_id INTEGER NOT NULL,filename TEXT NOT NULL,safe_filename TEXT NOT NULL,filepath TEXT NOT NULL,mime_type TEXT,size INTEGER NOT NULL DEFAULT 0,sha256 TEXT NOT NULL,scan_status TEXT NOT NULL DEFAULT 'PENDING',scan_result TEXT,created_at DATETIME NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(email_id)REFERENCES emails(id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tags(id INTEGER PRIMARY KEY AUTOINCREMENT,tg_id INTEGER NOT NULL,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#6366f1',created_at DATETIME NOT NULL DEFAULT(datetime('now')),UNIQUE(tg_id,name),FOREIGN KEY(tg_id)REFERENCES users(tg_id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS filters(id INTEGER PRIMARY KEY AUTOINCREMENT,tg_id INTEGER NOT NULL,alias_address TEXT,name TEXT NOT NULL,priority INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,match_field TEXT NOT NULL,match_type TEXT NOT NULL,match_value TEXT NOT NULL,action TEXT NOT NULL,action_params TEXT NOT NULL DEFAULT '{}',created_at DATETIME NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(tg_id)REFERENCES users(tg_id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS contacts(id INTEGER PRIMARY KEY AUTOINCREMENT,tg_id INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,notes TEXT,trusted INTEGER NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT(datetime('now')),UNIQUE(tg_id,email),FOREIGN KEY(tg_id)REFERENCES users(tg_id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auto_reply_log(id INTEGER PRIMARY KEY AUTOINCREMENT,alias_address TEXT NOT NULL,sender TEXT NOT NULL,replied_at DATETIME NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS forwarding_log(id INTEGER PRIMARY KEY AUTOINCREMENT,email_id INTEGER NOT NULL,destination TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_attempt_at DATETIME,error TEXT,created_at DATETIME NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS idempotency(key TEXT PRIMARY KEY,created_at DATETIME NOT NULL DEFAULT(datetime('now')));
